          lastToken.raw += token.raw;
          lastToken.text += token.text;
        } else {
          tokens.push(token);
        }
        continue;
      }
      if (this.state.linkRejected) {
        // The rejected reflink is re-scanned as plain text, so its contents were
        // masked for nothing: unmask them so em and strong can match inside it.
        // Keep the leading '[' masked-free and mask the rest from scratch.
        maskedSrc = maskedSrc.slice(0, maskedSrc.length - src.length) + '[' + this.maskInline(src.slice(1));
      }

      // em & strong
      if (token = this.tokenizer.emStrong(src, maskedSrc, prevChar)) {
        src = src.substring(token.raw.length);
